// Native-only fixed helper capability. No policy/path/hash/role is supplied by
// Node or C++; the fully authenticated running daemon policy is its only input.
fileprivate final class AuxAuthenticatedPtyHelper {
    let policy: AuxAuthenticatedFreshBootstrapPolicy
    let path: String
    let descriptors: [Int32]
    let entries: [(Int32, String, Int32, stat)]
    init(policy: AuxAuthenticatedFreshBootstrapPolicy, path: String,
         descriptors: [Int32], entries: [(Int32, String, Int32, stat)]) {
        self.policy = policy; self.path = path
        self.descriptors = descriptors; self.entries = entries
    }
    deinit {
        // An inherited capability must not close a reused child descriptor.
        if getpid() == auxImagePreparationProcess {
            for descriptor in descriptors.reversed() { close(descriptor) }
        }
    }
}
