// Exact finite resource reader shared by full image validation/preparation.
// It never launches the helper, calls a Node initializer or changes file mode.
extension AuxSignedFreshBootstrapPolicyLoader {
    fileprivate static func ptyResource(bundle:String,artifact:AuxFreshBootstrapPtyArtifact,executable:Bool)throws->Data {
        guard [AuxFreshBootstrapPtyArtifacts.modulePath,AuxFreshBootstrapPtyArtifacts.helperPath].contains(artifact.relativePath),
              executable==(artifact.relativePath==AuxFreshBootstrapPtyArtifacts.helperPath),try canonical(bundle)==bundle else{throw AuxFreshBootstrapPolicyError.path}
