        var parent=open(bundle,O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC)
        guard parent>=0 else{throw AuxFreshBootstrapPolicyError.path};held.append(parent);_ = try metadata(parent,directory:true)
        let parts=artifact.relativePath.split(separator:"/").map(String.init)
        for (index,name) in parts.enumerated() {
            let directory=index != parts.count-1
            let fd=openat(parent,name,O_RDONLY|O_NOFOLLOW|O_CLOEXEC|O_NONBLOCK|(directory ? O_DIRECTORY:0))
            guard fd>=0 else{throw AuxFreshBootstrapPolicyError.path};held.append(fd)
            _ = try metadata(fd,directory:directory,maximumSize:Int64(artifact.bytes));try sameEntry(parent,name,fd)
            entries.append((parent,name,fd));parent=fd
        }
        let before=try metadata(parent,directory:false,maximumSize:Int64(artifact.bytes))
        guard before.st_size==Int64(artifact.bytes),!executable || before.st_mode & 0o111 != 0 else{throw AuxFreshBootstrapPolicyError.path}
        var bytes=[UInt8](repeating:0,count:artifact.bytes),offset=0
