        guard bytes.count>=32,Array(bytes[0..<8])==[0xcf,0xfa,0xed,0xfe,0x0c,0x00,0x00,0x01],
              Array(bytes[12..<16])==(executable ? [2,0,0,0]:[8,0,0,0]) else{throw AuxFreshBootstrapPolicyError.image}
        let data=Data(bytes);guard freshBootstrapDigest(data)==artifact.sha256 else{throw AuxFreshBootstrapPolicyError.image}
