    }
}

// Native-only fixed helper capability. No policy/path/hash/role is supplied by
// Node or C++; the fully authenticated running daemon policy is its only input.
fileprivate final class AuxAuthenticatedPtyHelper {
    let policy: AuxAuthenticatedFreshBootstrapPolicy
    let path: String
    let descriptors: [Int32]
    let entries: [(Int32, String, Int32, stat)]
    init(policy: AuxAuthenticatedFreshBootstrapPolicy, path: String,
         descriptors: [Int32], entries: [(Int32, String, Int32, stat)]) {
        self.policy = policy; self.path = path
        self.descriptors = descriptors; self.entries = entries
    }
    deinit {
        // An inherited capability must not close a reused child descriptor.
        if getpid() == auxImagePreparationProcess {
            for descriptor in descriptors.reversed() { close(descriptor) }
        }
    }
}
extension AuxSignedFreshBootstrapPolicyLoader {
    fileprivate static func capturePtyHelper() throws -> AuxAuthenticatedPtyHelper {
        let policy = try load()
        guard geteuid() != 0, policy.contents.embeddedDaemon,
              policy.contents.role == .daemon,
              let artifact = policy.contents.linkedPtyHelper ?? policy.contents.ptyArtifacts?.helper else { throw AuxFreshBootstrapPolicyError.policy }
        let path = policy.bundlePath + "/" + artifact.relativePath
        guard try canonical(path) == path else { throw AuxFreshBootstrapPolicyError.path }
        var descriptors = [Int32]()
        var entries: [(Int32, String, Int32, stat)] = []
        var transferred = false
        defer { if !transferred { for fd in descriptors.reversed() { close(fd) } } }
        var parent = open("/", O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
        guard parent >= 0 else { throw AuxFreshBootstrapPolicyError.path }
        descriptors.append(parent)
        let root = try metadata(parent, directory: true)
        guard root.st_uid == 0 else { throw AuxFreshBootstrapPolicyError.path }
        entries.append((-1, "", parent, root))
        let components = path.dropFirst().split(separator: "/", omittingEmptySubsequences: false).map(String.init)
        for (index, name) in components.enumerated() {
            let directory = index != components.count - 1
            let descriptor = openat(parent, name, O_RDONLY | O_NOFOLLOW | O_CLOEXEC | O_NONBLOCK | (directory ? O_DIRECTORY : 0))
            guard descriptor >= 0 else { throw AuxFreshBootstrapPolicyError.path }
            descriptors.append(descriptor)
            let captured = try metadata(descriptor, directory: directory, maximumSize: Int64(artifact.bytes))
            guard captured.st_uid == 0 || (policy.contents.includesFixedLinkedPty && captured.st_uid==geteuid()) else { throw AuxFreshBootstrapPolicyError.path }
            try sameEntry(parent, name, descriptor)
            entries.append((parent, name, descriptor, captured)); parent = descriptor
        }
        let capability = AuxAuthenticatedPtyHelper(policy: policy, path: path, descriptors: descriptors, entries: entries)
        // Ownership transfers before throwing validation so exactly one owner
        // closes the complete chain on every error path.
        transferred = true
        try revalidatePtyHelper(capability)
        return capability
    }
    fileprivate static func revalidatePtyHelper(_ helper: AuxAuthenticatedPtyHelper) throws {
        guard getpid() == auxImagePreparationProcess, geteuid() != 0 else { throw AuxFreshBootstrapPolicyError.identity }
        let current = try load()
        guard current.contents.embeddedDaemon, current.contents.role == .daemon,
              current.policySha256 == helper.policy.policySha256,
              current.hostCdHash == helper.policy.hostCdHash,
              current.bundlePath == helper.policy.bundlePath,
              let artifact = current.contents.linkedPtyHelper ?? current.contents.ptyArtifacts?.helper,
              helper.path == current.bundlePath + "/" + artifact.relativePath else { throw AuxFreshBootstrapPolicyError.identity }
        func namespace() throws {
            guard let root = helper.entries.first else { throw AuxFreshBootstrapPolicyError.path }
            let actualRoot = open("/", O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
            guard actualRoot >= 0 else { throw AuxFreshBootstrapPolicyError.path }
            defer { close(actualRoot) }
            let actualRootMetadata = try metadata(actualRoot, directory: true)
            guard actualRootMetadata.st_dev == root.3.st_dev,
                  actualRootMetadata.st_ino == root.3.st_ino else { throw AuxFreshBootstrapPolicyError.path }
            for (parent, name, descriptor, original) in helper.entries {
                let directory = original.st_mode & mode_t(S_IFMT) == mode_t(S_IFDIR)
                let now = try metadata(descriptor, directory: directory, maximumSize: Int64(artifact.bytes))
                guard (now.st_uid == 0 || (current.contents.includesFixedLinkedPty && now.st_uid==geteuid())), now.st_dev == original.st_dev, now.st_ino == original.st_ino,
                      now.st_mode == original.st_mode, now.st_gid == original.st_gid else { throw AuxFreshBootstrapPolicyError.path }
                if parent >= 0 { try sameEntry(parent, name, descriptor) }
                if !directory {
                    guard now.st_size == original.st_size, now.st_nlink == original.st_nlink,
                          now.st_mtimespec.tv_sec == original.st_mtimespec.tv_sec,
                          now.st_mtimespec.tv_nsec == original.st_mtimespec.tv_nsec,
                          now.st_ctimespec.tv_sec == original.st_ctimespec.tv_sec,
                          now.st_ctimespec.tv_nsec == original.st_ctimespec.tv_nsec else { throw AuxFreshBootstrapPolicyError.path }
                }
            }
        }
        try namespace()
        let bytes = try ptyResource(bundle: current.bundlePath, artifact: artifact, executable: true)
        var code: SecStaticCode?
        let created = SecStaticCodeCreateWithPath(URL(fileURLWithPath: helper.path) as CFURL, [], &code)
        guard created == errSecSuccess, let code else { throw AuxFreshBootstrapPolicyError.signature(created) }
        let valid = SecStaticCodeCheckValidity(code, flags, try requirement())
        guard valid == errSecSuccess else { throw AuxFreshBootstrapPolicyError.signature(valid) }
        try validateCapturedFreshBootstrapPtySignature(signature(signingInfo(code)), artifact: artifact)
        var own: SecCode?, ownStatic: SecStaticCode?
        let copied = SecCodeCopySelf([], &own)
        guard copied == errSecSuccess, let own else { throw AuxFreshBootstrapPolicyError.signature(copied) }
        let staticStatus = SecCodeCopyStaticCode(own, [], &ownStatic)
        guard staticStatus == errSecSuccess, let ownStatic else { throw AuxFreshBootstrapPolicyError.signature(staticStatus) }
        let relative = String(artifact.relativePath.dropFirst("Contents/".count))
        let sealed = SecCodeValidateFileResource(ownStatic, relative as CFString, bytes as CFData, [])
        guard sealed == errSecSuccess else { throw AuxFreshBootstrapPolicyError.signature(sealed) }
        try namespace()
        let final = try load()
        guard final.policySha256 == current.policySha256, final.hostCdHash == current.hostCdHash,
              final.bundlePath == current.bundlePath else { throw AuxFreshBootstrapPolicyError.identity }
    }
}

// Never-reused registry IDs avoid dereferencing caller-supplied pointers or
// accepting a stale allocation address as a new capability. Security and FD
// validation run outside this mutex with a locally retained strong reference.
private let auxPtyHelperLock = NSLock()
private var auxPtyHelpers = [UInt: AuxAuthenticatedPtyHelper]()
private var auxPtyHelperNext: UInt = 1
private func auxCapturedPtyHelper(_ opaque: UnsafeMutableRawPointer?) -> AuxAuthenticatedPtyHelper? {
    guard getpid() == auxImagePreparationProcess, let opaque else { return nil }
    auxPtyHelperLock.lock(); defer { auxPtyHelperLock.unlock() }
    return auxPtyHelpers[UInt(bitPattern: opaque)]
}
@_cdecl("AuxCaptureAuthenticatedPtyHelper")
func AuxCaptureAuthenticatedPtyHelper(_ output: UnsafeMutablePointer<UnsafeMutableRawPointer?>?) -> Int32 {
    guard getpid() == auxImagePreparationProcess, let output else { return -1 }
    output.pointee = nil
    auxImagePreparationLock.lock(); let prepared = auxImagePreparationComplete; auxImagePreparationLock.unlock()
    guard prepared else { return -1 }
    do {
        let helper = try AuxSignedFreshBootstrapPolicyLoader.capturePtyHelper()
        auxPtyHelperLock.lock(); defer { auxPtyHelperLock.unlock() }
        guard auxPtyHelperNext < UInt.max, let opaque = UnsafeMutableRawPointer(bitPattern: auxPtyHelperNext) else { return -1 }
        auxPtyHelpers[auxPtyHelperNext] = helper; auxPtyHelperNext += 1
        output.pointee = opaque; return 0
    } catch { return -1 }
}
@_cdecl("AuxAuthenticatedPtyHelperRevalidate")
func AuxAuthenticatedPtyHelperRevalidate(_ opaque: UnsafeMutableRawPointer?) -> Int32 {
    guard let helper = auxCapturedPtyHelper(opaque) else { return -1 }
    do { try AuxSignedFreshBootstrapPolicyLoader.revalidatePtyHelper(helper); return 0 } catch { return -1 }
}
@_cdecl("AuxAuthenticatedPtyHelperCopyPath")
func AuxAuthenticatedPtyHelperCopyPath(_ opaque: UnsafeMutableRawPointer?, _ output: UnsafeMutablePointer<CChar>?,
                                     _ capacity: UInt32, _ count: UnsafeMutablePointer<UInt32>?) -> Int32 {
    guard getpid() == auxImagePreparationProcess, let count else { return -1 }
    count.pointee = 0
    guard let output, capacity > 0, capacity <= 4096, let helper = auxCapturedPtyHelper(opaque) else { return -1 }
    output.pointee = 0
    do {
        try AuxSignedFreshBootstrapPolicyLoader.revalidatePtyHelper(helper)
        let bytes = helper.path.utf8CString
        guard bytes.count <= Int(capacity), bytes.count <= 4096 else { return -1 }
        for index in bytes.indices { output[index] = bytes[index] }
        count.pointee = UInt32(bytes.count); return 0
    } catch { return -1 }
}
@_cdecl("AuxAuthenticatedPtyHelperRelease")
func AuxAuthenticatedPtyHelperRelease(_ opaque: UnsafeMutableRawPointer?) {
    guard getpid() == auxImagePreparationProcess, let opaque else { return }
    auxPtyHelperLock.lock()
    let helper = auxPtyHelpers.removeValue(forKey: UInt(bitPattern: opaque))
    auxPtyHelperLock.unlock()
    withExtendedLifetime(helper) {}
}

